import java.sql.*;
import java.util.*;

public class Main {
    private static final String URL = "jdbc:h2:mem:bank;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";

    static void siapkan(Connection c) throws SQLException {
        try (Statement st = c.createStatement()) {
            st.execute("CREATE TABLE rekening (id INT PRIMARY KEY, nama VARCHAR(50) NOT NULL, saldo INT NOT NULL CHECK (saldo >= 0))");
            st.executeUpdate("INSERT INTO rekening VALUES (1, 'Sari', 100000), (2, 'Budi', 50000)");
        }
    }

    static void cetakSaldo(Connection c) throws SQLException {
        try (Statement st = c.createStatement();
             ResultSet rs = st.executeQuery("SELECT nama, saldo FROM rekening ORDER BY id")) {
            while (rs.next()) {
                System.out.println("  " + rs.getString("nama") + ": " + rs.getInt("saldo"));
            }
        }
    }

    static void transfer(Connection c, int dari, int ke, int jumlah) throws SQLException {
        try (PreparedStatement tambah = c.prepareStatement("UPDATE rekening SET saldo = saldo + ? WHERE id = ?");
             PreparedStatement kurang = c.prepareStatement("UPDATE rekening SET saldo = saldo - ? WHERE id = ?")) {
            tambah.setInt(1, jumlah);
            tambah.setInt(2, ke);
            tambah.executeUpdate();
            kurang.setInt(1, jumlah);
            kurang.setInt(2, dari);
            kurang.executeUpdate();
        }
    }

    public static void main(String[] args) throws SQLException {
        try (Connection c = DriverManager.getConnection(URL, "sa", "")) {
            siapkan(c);
            System.out.println("Awal:");
            cetakSaldo(c);
            transfer(c, 1, 2, 30000);
            System.out.println("Transfer 30000 dari Sari ke Budi berhasil");
            cetakSaldo(c);
        }
    }
}

