public class Main {
    private static final String URL = "jdbc:h2:mem:toko;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";

    static void siapkan(Connection c) throws SQLException {
        try (Statement st = c.createStatement()) {
            st.execute("CREATE TABLE produk (id INT PRIMARY KEY, nama VARCHAR(50) NOT NULL, stok INT NOT NULL CHECK (stok >= 0))");
            st.execute("CREATE TABLE penjualan (id INT AUTO_INCREMENT PRIMARY KEY, produk_id INT NOT NULL, jumlah INT NOT NULL)");
            st.executeUpdate("INSERT INTO produk VALUES (1, 'Pensil', 10), (2, 'Buku', 3)");
        }
    }

    static void laporan(Connection c) throws SQLException {
        try (Statement st = c.createStatement();
             ResultSet rs = st.executeQuery("SELECT (SELECT SUM(stok) FROM produk), (SELECT COUNT(*) FROM penjualan)")) {
            rs.next();
            System.out.println("Stok total " + rs.getInt(1) + ", penjualan tercatat " + rs.getInt(2));
        }
    }

    static boolean jual(Connection c, int produkId, int jumlah) throws SQLException {
        try (PreparedStatement catat = c.prepareStatement("INSERT INTO penjualan (produk_id, jumlah) VALUES (?, ?)");
             PreparedStatement kurangi = c.prepareStatement("UPDATE produk SET stok = stok - ? WHERE id = ?")) {
            catat.setInt(1, produkId);
            catat.setInt(2, jumlah);
            catat.executeUpdate();
            kurangi.setInt(1, jumlah);
            kurangi.setInt(2, produkId);
            kurangi.executeUpdate();
            return true;
        } catch (SQLException e) {
            return false;
        }
    }

    public static void main(String[] args) throws SQLException {
        Scanner in = new Scanner(System.in);
        try (Connection c = DriverManager.getConnection(URL, "sa", "")) {
            siapkan(c);
            while (in.hasNextLine()) {
                String[] d = in.nextLine().split(" ");
                int id = Integer.parseInt(d[0]);
                int jumlah = Integer.parseInt(d[1]);
                System.out.println("Jual " + jumlah + " produk " + id + ": " + (jual(c, id, jumlah) ? "berhasil" : "gagal"));
            }
            laporan(c);
        }
    }
}

